import java.util.*;
import java.io.*;

public class Variant3 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        String sLine = br.readLine();
        char[] s = sLine.toCharArray();

        int[][][][] dp = new int[3][n+1][n+1][n+1];
        for (int[][][] a : dp)
            for (int[][] b : a)
                for (int[] c : b)
                    Arrays.fill(c, Integer.MAX_VALUE);

        int countV = 0, countK = 0, countE = 0;
        for (char c : s) {
            if (c == 'V') countV++;
            else if (c == 'K') countK++;
            else countE++;
        }

        dp[2][0][0][0] = 0;
        int[][][][] poss = new int[3][countV+1][countK+1][countE+1];
        for (int i = 0; i <= countV; i++)
            for (int j = 0; j <= countK; j++)
                for (int k = 0; k <= countE; k++)
                    for (int l = 0; l < 3; l++)
                        poss[l][i][j][k] = pos(s, i, j, k, l);

        for (int i = 0; i <= countV; i++)
            for (int j = 0; j <= countK; j++)
                for (int k = 0; k <= countE; k++) {
                    if (i + 1 <= countV && poss[0][i][j][k] != -1) {
                        int v = poss[0][i][j][k];
                        dp[0][i + 1][j][k] = Math.min(dp[0][i + 1][j][k], dp[2][i][j][k] + v);
                        dp[0][i + 1][j][k] = Math.min(dp[0][i + 1][j][k], dp[1][i][j][k] + v);
                        dp[0][i + 1][j][k] = Math.min(dp[0][i + 1][j][k], dp[0][i][j][k] + v);
                    }
                    if (j + 1 <= countK && poss[1][i][j][k] != -1) {
                        int v = poss[1][i][j][k];
                        dp[1][i][j + 1][k] = Math.min(dp[1][i][j + 1][k], dp[2][i][j][k] + v);
                        dp[1][i][j + 1][k] = Math.min(dp[1][i][j + 1][k], dp[1][i][j][k] + v);
                    }
                    if (k + 1 <= countE && poss[2][i][j][k] != -1) {
                        int v = poss[2][i][j][k];
                        dp[2][i][j][k + 1] = Math.min(dp[2][i][j][k + 1], dp[2][i][j][k] + v);
                        dp[2][i][j][k + 1] = Math.min(dp[2][i][j][k + 1], dp[1][i][j][k] + v);
                        dp[2][i][j][k + 1] = Math.min(dp[2][i][j][k + 1], dp[0][i][j][k] + v);
                    }
                }
        System.out.println(Math.min(Math.min(dp[0][countV][countK][countE], dp[1][countV][countK][countE]), dp[2][countV][countK][countE]));
    }

    static int pos(char[] s, int a, int b, int c, int k) {
        int ret = 0;
        for (char x : s) {
            if (x == 'V') {
                if (a == 0) {
                    if (k == 0) return ret;
                    ret++;
                } else {
                    a--;
                }
            } else if (x == 'K') {
                if (b == 0) {
                    if (k == 1) return ret;
                    ret++;
                } else {
                    b--;
                }
            } else {
                if (c == 0) {
                    if (k == 2) return ret;
                    ret++;
                } else {
                    c--;
                }
            }
        }
        return -1;
    }
}
